// Regular expressions are defined over an alphabet using 
// atoms and operations.
// Atoms include the empty set, empty string, and some 
// symbol from the alphabet. Each is a regex.
// Operations creates new regexs using other regexs.
// Operations include union, concatonation, and kleene star.

// Regular expressions recognize a string iff that string
// can be generated by combining atoms and operations.

// Regular expressions can be implemented internally using 
// an NFA structure of nodes and state transitions.

#[derive(Clone, Debug)]
pub struct Rregex {
    nodes: Vec<Node>,       // All Node objects owned by this Rregex.
    start: NodeID,           // Index into nodes.
    accept: Option<NodeID>,  // Index into nodes, if there is an accept state.
}

impl Rregex {

    // -- CONSTRUCTORS --

    pub fn get_empty_set() -> Self {
        // Empty set NFA has a single start and no accept.
        Self {
            nodes: vec![Node::new()],
            start: NodeID(0),
            accept: None,
        }
    }

    pub fn get_epsilon() -> Self {
        // {\epsilon} has a single state which is start and accept.
        Self {
            nodes: vec![Node::new()],
            start: NodeID(0),
            accept: Some(NodeID(0)),
        }
    }

    // The language {s} is denoted by the regex s iff s \in alphabet.
    // get_symbol(s) returns the Rregex s.
    pub fn get_symbol(s: char) -> Self {
        // Has a start state which transitions 
        // to an accept state on input s.

        let mut start_node = Node::new();
        let accept_node = Node::new();

        // start_node transitions to accept_node on s.
        start_node.add_outgoing_transition(NodeID(1), Some(s));

        Self {
            nodes: vec![start_node, accept_node],
            start: NodeID(0),
            accept: Some(NodeID(1)),
        }
    }

    pub fn union(mut opt_1: Rregex, mut opt_2: Rregex) -> Self {
        // Take necessary values from opt_1.
        let (nodes_1, start_1, accept_1) = opt_1.extract_nodes_start_accept();
        drop(opt_1);

        // Check if opt_1 recognizes the empty set (nothing).
        // R U {} = R
        if accept_1.is_none() {
            // Return opt_2.
            return opt_2;
        }
        
        // Take necessary values from opt_2
        let (mut nodes_2, start_2_from_opt_2, accept_2_from_opt_2) = opt_2.extract_nodes_start_accept();
        drop(opt_2);

        // Check if opt_2 recognizes the empty set (nothing).
        // R U {} = R
        if accept_2_from_opt_2.is_none() {
            // Return opt_1 by reconstructing it.
            return Self {
                nodes: nodes_1,
                start: start_1,
                accept: accept_1,
            };
        }

        // Neither accept_1 nor accept_2 are None.
        let accept_1_index = accept_1.unwrap().0;
        let accept_2_index = accept_2_from_opt_2.unwrap().0 + nodes_1.len();
        // Prepare fields and manipulate graphs.
        // nodes is [nodes_1, nodes_2, start_node, accept_node].
        let start_2 = NodeID(start_2_from_opt_2.0 + nodes_1.len());
        let start_nodeid = NodeID(nodes_1.len() + nodes_2.len());
        let accept_nodeid = NodeID(start_nodeid.0 + 1);
        
        let accept_node = Node::new();
        let mut start_node = Node::new();
        // start_node transitions to start of opt_1 and start of opt_2 on epsilon.
        start_node.add_outgoing_transition(start_1, None);
        start_node.add_outgoing_transition(start_2, None);

        // Adjust internal destinations in nodes_2.
        for node in &mut nodes_2 {
            for edge in &mut node.transitions {
                edge.destination.0 += nodes_1.len();
            }
        }

        let mut nodes: Vec<Node> = nodes_1.into_iter()  // opt_1 nodes
                .chain(nodes_2.into_iter())             // opt_2 nodes
                .chain(std::iter::once(start_node))     // new start_node
                .chain(std::iter::once(accept_node))    // new accept_node
                .collect();

        // accept_1 and accept_2 transition to accept_node on epsilon.
        nodes[accept_1_index].add_outgoing_transition(accept_nodeid, None);
        nodes[accept_2_index].add_outgoing_transition(accept_nodeid, None);

        // Return constructed Self.
        Self {
            nodes: nodes,
            start: start_nodeid,
            accept: Some(accept_nodeid),
        }
    }

    pub fn concat(first: Rregex, second: Rregex) -> Self {

        // Check if either recognizes empty set (nothing).
        if first.accept.is_none() || second.accept.is_none() {
            return Rregex::get_empty_set();
        }

        let first_nodes_len = first.nodes.len();
        let mut nodes = first.nodes.clone();
        for node in second.nodes {
            let mut next = node.clone();
            for edge in &mut next.transitions {
                edge.destination.0 += first_nodes_len;
            }
            nodes.push(next);
        }
        
        // Transition from first.accept to second.start on epsilon.
        nodes[first.accept.unwrap().0].add_outgoing_transition(
            NodeID(second.start.0 + first_nodes_len),
            None
        );

        Self {
            nodes: nodes,
            start: first.start,
            accept: Some(NodeID(second.accept.unwrap().0 + first_nodes_len)),
        }
    }

    //pub fn star(operand: Rregex) -> Self


    // -- USABILITY INTERFACE --

    // Determine whether self recognizes s.
    pub fn recognizes(&self, s: &str) -> bool {
        // Consume every char in s by repeatedly performing 
        // epsilon closures, traversing any edges labeled the
        // next char in s, and keeping track of all current states.
        // Iff by the time s is consumed, Some(accept) is in list
        // of current states, then return true.

        let Some(accept) = self.accept else {
            // self recognizes the empty set (nothing).
            return false;
        };

        // Take epsilon closure of self.start.
        let mut current_states = self.epsilon_closure(
            [self.start].into_iter().collect()
        );

        // Consume every character in s.
        for c in s.chars() {
            let mut next_states = std::collections::HashSet::new();

            for &state in &current_states {
                for trans in &self.nodes[state.0].transitions {
                    if trans.matches(c) {
                        next_states.insert(trans.destination);
                    }
                }
            }

            // Transition to all found states and their epsilon closures.
            current_states = self.epsilon_closure(next_states);

            if current_states.is_empty() {
                // No possible states remain. Can't recognize.
                return false;
            }
        }

        // True iff accept is in current_states.
        current_states.contains(&accept)
    }


    // -- PRIVATE HELPERS AND MUTATORS --

    // Transfer ownership of all fields out of self
    fn extract_nodes_start_accept(&mut self) -> (Vec<Node>, NodeID, Option<NodeID>) {
        (
            std::mem::take(&mut self.nodes), 
            std::mem::take(&mut self.start), 
            std::mem::take(&mut self.accept)
        )
    }

    // Find all nodes reachable from a set of nodes by 
    // traversing only epsilon transitions.
    fn epsilon_closure(&self, states: std::collections::HashSet<NodeID>) -> std::collections::HashSet<NodeID> {
        let mut closure = states;
        // stack tracks states whose epsilon transitions need to be explored.
        let mut stack: Vec<NodeID> = closure.iter().copied().collect();

        while let Some(state) = stack.pop() {
            for edge in &self.nodes[state.0].transitions {
                if edge.is_epsilon() && closure.insert(edge.destination) {
                    stack.push(edge.destination);
                }
            }
        }

        closure
    }

}


#[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq)]
struct NodeID(usize);


#[derive(Clone, Debug)]
struct Node {
    // A Node owns 0 or more outgoing transitions.
    transitions: Vec<Edge>,
}

impl Node {
    // A Node by default has 0 transitions (empty Vec).
    fn new() -> Self {
        Self {
            transitions: Vec::new(),
        }
    }

    fn add_outgoing_transition(&mut self, to: NodeID, symbol: Option<char>) {
        match symbol {
            Some(s) => self.transitions.push(Edge::new_symbol(to, s)),
            None => self.transitions.push(Edge::new_epsilon(to)),
        };
    }
}


#[derive(Clone, Debug)]
struct Edge {
    destination: NodeID,     // Index into owner regex's Vec<Node>.
    symbol: Option<char>,
}

impl Edge {
    // Initialize this Edge using epsilon transition.
    fn new_epsilon(node_id_destination: NodeID) -> Self {
        Self {
            destination: node_id_destination,
            symbol: None,
        }
    }

    // Initialize this Edge using given transition (on symbol).
    fn new_symbol(node_id_destination: NodeID, symbol: char) -> Self {
        Self {
            destination: node_id_destination,
            symbol: Some(symbol),
        }
    }

    fn is_epsilon(&self) -> bool {
        self.symbol.is_none()
    }

    fn matches(&self, c: char) -> bool {
        match self.symbol {
            None => false,
            Some(s) => c == s,
        }
    }
}

